"use strict";(globalThis.webpackChunkelemental_selenium||=[]).push([[75393],{664955(e){e.exports=JSON.parse('{"tag":{"label":"sauce labs","permalink":"/tips/tags/sauce-labs","allTagsPath":"/tips/tags","count":6,"items":[{"id":"cloud/26-cloud","title":"Cloud","description":"In order to test features in a previous version of Chrome, you would need to run a virtual machine (VM) on your computer with a legit version of Windows installed on the VM.","permalink":"/tips/26-cloud"},{"id":"sauce-visual/74-sauce-visual","title":"How to Check Screenshots with Sauce Labs Visual","description":"Comparing screenshots in the test code means keeping baselines for every browser and operating system, and reviewing the differences by hand. Sauce Labs Visual stores the baselines, compares the snapshots, and shows the changes for review.","permalink":"/tips/74-sauce-visual"},{"id":"download-from-a-remote-browser/28-download-from-a-remote-browser","title":"How To Download Files From a Remote Browser","description":"When the browser runs on another machine (a Selenium Grid, a cloud provider), the files it downloads stay on that machine. Here is how to get them back to your tests.","permalink":"/tips/28-download-from-a-remote-browser"},{"id":"mobile/30-mobile","title":"How to Run a Test on a Real Mobile Device","description":"Your users run your app on real phones, not on emulators. Here is how to run a first test on a real Android phone and a real iPhone on Sauce Labs, with Appium, Mobilewright, Espresso and XCUITest.","permalink":"/tips/30-mobile"},{"id":"one-test-multiple-browsers/41-one-test-multiple-browsers","title":"How to Run a Test on Multiple Browsers","description":"You\'ll occasionally have something that you want to test across multiple browsers. It would be nice to run your test once and have it execute against all the browsers you care about. Unfortunately this functionality doesn\'t come out of the box with most testing frameworks.","permalink":"/tips/41-one-test-multiple-browsers"},{"id":"upload-to-a-remote-browser/68-upload-to-a-remote-browser","title":"How To Upload Files to a Remote Browser","description":"When the browser runs on another machine (a Selenium Grid, a cloud provider), it cannot see the files on our machine. Here is how to send a file to it and upload it.","permalink":"/tips/68-upload-to-a-remote-browser"}],"unlisted":false}}')}}]);